function newInteger(n) {
  // How many integers in 1..x have no digit 9: count digit by digit, then binary search for the n-th.
  const countUpTo = (x) => {
    const digits = String(x);
    let count = 0;
    for (let i = 0; i < digits.length; i++) {
      const d = Number(digits[i]);
      count += Math.min(d, 9) * Math.pow(9, digits.length - 1 - i);
      if (d === 9) return count - 1;
    }
    return count;
  };
  let low = 1, high = 1e10;
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (countUpTo(mid) >= n) high = mid; else low = mid + 1;
  }
  return low;
}

