function generate(rand, size) {
  if (size === 'large') return [1 + Math.floor(rand() * 800000000)];
  const r = rand();
  if (r < 0.2) return [1 + Math.floor(rand() * 20)];
  if (r < 0.4) {
    const powers = [9, 81, 729];
    const power = powers[Math.floor(rand() * powers.length)];
    return [power + Math.floor(rand() * 3) - 1];
  }
  return [1 + Math.floor(rand() * 3000)];
}
